<template>
  <f-btn
    class="q-ml-sm"
    :icon="accounts_loaded ? 'save' : ''"
    @click="onSave"
    :disabled="is_view_readonly || !accounts_loaded"
  >
    <q-tooltip>{{ $t('save') }}</q-tooltip>
    <q-spinner
      v-if="!accounts_loaded"
      size="20px"
      color="white"
      class="q-mr-xs"
    />
  </f-btn>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { defineComponent } from 'vue';
import { storeToRefs } from 'pinia';
import type { dynamicObj } from 'src/pages/assets';
import helperMixin from 'src/mixins/helperMixin';
import { ApiExceptions } from 'src/exceptions/index';
import { useDocumentStore, useAutoAccountingStore } from 'src/store/main';
export default defineComponent({
  mixins: [helperMixin],
  props: {},
  components: {},
  watch: {},
  computed: {},
  methods: {
    async onSave() {
      try {
        if (this.is_view_readonly) {
          return;
        }
        this.processing = true;
        this.prepareJsonForSave();
        const response = await this.saveDocument(this.record.doc_id);
        if (response.success === false) {
          throw { message: response.message };
        }
        this.setDataToCache();
        notify.success(this.$t('MSG_SAVE'));
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.processing = false;
      }
    },

    prepareJsonForSave() {
      this.record.accounting = {
        mode: this.accounting_mode,
        line_items: this.lineItems,
      };
    },
  },
  setup() {
    const doc_store = useDocumentStore();
    const { record, processing } = storeToRefs(doc_store);
    const { saveDocument, setDataToCache } = doc_store;

    const auto_accounting_store = useAutoAccountingStore();
    const { lineItems, is_view_readonly, accounting_mode, accounts_loaded } =
      storeToRefs(auto_accounting_store);

    return {
      setDataToCache,
      saveDocument,
      record,
      processing,
      lineItems,
      is_view_readonly,
      accounting_mode,
      accounts_loaded,
    };
  },
});
</script>
<style scoped lang="scss"></style>
