<template>
  <div
    class="border-left-bdbdbd border-bottom-bdbdbd border-right-bdbdbd border-top-bdbdbd"
  >
    <q-expansion-item expand-separator header-class="highlighted-back">
      <template v-slot:header>
        <span> {{ $t('train_data') }}</span>
        <q-space />
      </template>
      <q-separator />

      <div class="row mb-10 mt-8 q-ml-sm full-width table-header">
        <div class="col-4" v-if="accounting_mode !== 'total_line'">
          <span class="q-ml-sm"> {{ $t('description') }} </span>
        </div>

        <div :class="accounting_mode !== 'total_line' ? 'col-6' : 'col-10'">
          <span class="q-ml-sm"> {{ $t('account') }} </span>
        </div>

        <div class="col-2"></div>
      </div>
      <template v-for="(item, index) in training_data" :key="index">
        <div class="row mb-10 mt-8 q-ml-sm full-width">
          <div class="col-4" v-if="accounting_mode !== 'total_line'">
            <q-input
              :readonly="true"
              dense
              outlined
              v-model="item['description']"
              :class="'q-pl-sm accouting-input '"
            >
              <template v-slot:append>
                <q-icon
                  v-if="errors[index]['description'] !== ''"
                  flat
                  dense
                  name="error"
                  size="24px"
                  color="red"
                >
                  <q-tooltip
                    class="bg-red"
                    anchor="bottom right"
                    self="top right"
                  >
                    {{ $t('FIELD_REQUIRED') }}
                  </q-tooltip>
                </q-icon>
              </template>
            </q-input>
          </div>

          <div
            class="account-container"
            :class="accounting_mode !== 'total_line' ? 'col-6' : 'col-10'"
          >
            <q-select
              dense
              tabindex="1"
              class="q-mr-sm q-pl-sm accounting-select"
              clearable
              use-input
              outlined
              v-model="item['ledger_account']"
              :loading="!accounts_loaded"
              :options="filterAccounts"
              @filter="filterAccountsEvent"
              @input-value="selectInputValue"
              :disable="is_view_readonly"
              emit-value
              map-options
            >
              <template v-slot:selected-item="scope">
                <div class="ellipsis">{{ scope.opt.label }}</div>
              </template>

              <template v-slot:option="scope">
                <q-item v-bind="scope.itemProps">
                  <q-item-section>
                    <q-item-label>
                      <span
                        v-html="highlightOption(scope.opt.label, input_value)"
                      ></span
                    ></q-item-label>
                  </q-item-section>
                </q-item>
              </template>

              <template v-slot:append>
                <q-icon
                  v-if="errors[index]['ledger_account'] !== ''"
                  flat
                  dense
                  name="error"
                  size="24px"
                  color="red"
                >
                  <q-tooltip
                    class="bg-red"
                    anchor="bottom right"
                    self="top right"
                  >
                    {{ $t('FIELD_REQUIRED') }}
                  </q-tooltip>
                </q-icon>
              </template>
            </q-select>
          </div>

          <div class="col-2 flex-center">
            <span
              tabindex="1"
              @click="deleteRow(index)"
              @keydown.enter="deleteRow(index)"
              class="cursor-pointer q-ml-sm mt-4"
              :class="is_view_readonly ? 'disabled' : ''"
            >
              <Icon icon="mdi:delete" width="22" height="22" />
            </span>
          </div>
        </div>
      </template>

      <q-card-actions align="right">
        <q-btn
          unelevated
          color="grey"
          class="q-mr-sm"
          :label="$t('refresh')"
          @click="refresh()"
        />
        <q-btn
          unelevated
          color="primary"
          class="q-mr-sm"
          :label="$t('train')"
          @click="trainModelProceed"
        />
      </q-card-actions>
    </q-expansion-item>
  </div>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';

import { defineComponent, ref } from 'vue';
import { storeToRefs } from 'pinia';
import { useAutoAccountingStore } from 'src/store/main';
import { autoAccountingApiService } from 'src/services';
import { ApiExceptions } from 'src/exceptions/index';
import { isEmptyString } from 'src/utils/general';
import type { dynamicObj } from 'src/pages/assets';
import helperMixin from 'src/mixins/helperMixin';
export default defineComponent({
  mixins: [helperMixin],
  props: {},
  
  watch: {
    accounting_mode: {
      handler: function (newVal, oldVal) {
        if (newVal !== oldVal) {
          this.init();
        }
      },
    },
  },
  computed: {},
  mounted: function () {
    this.init();
  },
  methods: {
    init() {
      try {
        this.training_data = [];
        this.input_value = '';
        if (!this.isValidData() || isEmptyString(this.supplier_name)) {
          return;
        }
        for (const item of this.lineItems) {
          if (
            this.accounting_mode === 'line_items' &&
            item.type === 'total_line_item'
          ) {
            continue;
          }

          if (
            this.accounting_mode === 'total_line' &&
            item.type === 'line_item'
          ) {
            continue;
          }
          this.addEmptyTrainingLine({
            description: item.description,
          });
        }
      } catch (err: any) {}
    },

    refresh() {
      if (this.is_view_readonly) {
        return;
      }
      if (!this.isValidData() || isEmptyString(this.supplier_name)) {
        notify.error(this.$t('missing_supplier_warning'));
        return;
      }
      this.init();
    },

    addEmptyTrainingLine(existing_item: dynamicObj = {}) {
      const basic_item = {
        supplier_name: this.supplier_name,
        ledger_account: '',
      } as dynamicObj;

      const item = Object.assign(existing_item, basic_item);
      this.training_data.push(item);

      const error_item = Object.assign(
        {},
        {
          ledger_account: '',
          description: '',
        },
      );

      this.errors.push(error_item);
    },

    renderTrainingData() {
      // check what needs to do here
    },

    deleteRow(index: number) {
      this.training_data.splice(index, 1);
      this.errors.splice(index, 1);
    },

    filterAccountsEvent(val: string, update: any, abort: any) {
      if (!val) {
        update(() => {
          this.filterAccounts = this.accounts;
        });
        return;
      }

      update(() => {
        this.filterAccounts = this.accountFilterByAnyValue(val);
      });
    },

    async trainModelProceed() {
      try {
        if (this.is_view_readonly) {
          return;
        }
        if (!this.isValidData() || isEmptyString(this.supplier_name)) {
          notify.error(this.$t('missing_supplier_warning'));
          return;
        }
        if (this.validateTrainingData()) {
          return;
        }
        this.showLoading();
        const data = { line_items: JSON.stringify(this.training_data) };
        const response = await autoAccountingApiService.trainModel(data);
        if (response.success === false) {
          throw { message: response.data };
        }

        const training_data = this.training_data.map((item: dynamicObj) => {
          delete item['ledger_account'];
          return item;
        });

        const line_items = this.getLineItemsForPredictionAccount();
        const params = {
          line_items: JSON.stringify(line_items),
        };
        this.getPredictions(params);
        notify.success(this.$t('train_model_success_test'));
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },

    validateTrainingData() {
      let has_error = false;
      for (const [index, item] of this.training_data.entries()) {
        this.errors[index]['supplier_name'] = '';
        if (item['supplier_name'] === '') {
          this.errors[index]['supplier_name'] = 'error';
          has_error = true;
        }

        this.errors[index]['ledger_account'] = '';
        if (item['ledger_account'] === '') {
          has_error = true;
          this.errors[index]['ledger_account'] = 'error';
        }

        this.errors[index]['description'] = '';
        if (
          this.accounting_mode === 'line_items' &&
          item['description'] === ''
        ) {
          has_error = true;
          this.errors[index]['description'] = 'error';
        }
      }

      return has_error;
    },

    // Auto-Complete
    selectInputValue(value: any) {
      this.input_value = value;
    },
  },
  setup() {
    const auto_accounting_store = useAutoAccountingStore();
    const {
      accountFilterByAnyValue,
      is_view_readonly,
      supplier_name,
      accounts,
      accounts_loaded,
      accounting_mode,
      lineItems,
    } = storeToRefs(auto_accounting_store);

    const {
      isValidData,
      getPredictions,
      getLineItemsForPredictionAccount,
      highlightOption,
    } = auto_accounting_store;
    const filterAccounts: any = ref(auto_accounting_store.accounts);
    return {
      isValidData,
      highlightOption,
      getLineItemsForPredictionAccount,
      lineItems,
      getPredictions,
      accounts_loaded,
      accounts,
      accountFilterByAnyValue,
      filterAccounts,
      accounting_mode,

      is_view_readonly,
      supplier_name,
      training_data: ref([] as dynamicObj[]),
      errors: ref([] as dynamicObj[]),
      input_value: ref(''),
    };
  },
});
</script>
<style scoped lang="scss"></style>
