<template>
  <div
    class="border-left-bdbdbd border-bottom-bdbdbd border-right-bdbdbd border-top-bdbdbd q-mt-sm"
  >
    <q-expansion-item expand-separator header-class="highlighted-back">
      <template v-slot:header>
        <span> {{ $t('test_data') }}</span>
        <q-space />
      </template>
      <q-separator />

      <!-- Predictions results -->
      <template v-if="test_clicked">
        <template v-if="total_line_predictions.length === 0">
          <div class="row q-pl-sm q-pt-sm total-line-item-area">
            <div class="col-12 flex flex-center">
              {{ $t('no_predictions_found') }}
            </div>
          </div>
        </template>

        <template v-for="(items, name) in predictions_by_mode" :key="name">
          <div class="row q-mt-sm">
            <div class="col-12 q-pl-sm text-weight-bold">
              {{ name }}
            </div>
            <template v-for="(item, index) in items" :key="index">
              <div class="col-11 q-mt-sm q-pl-md">
                <q-circular-progress
                  show-value
                  font-size="12px"
                  :value="item.percentage"
                  size="40px"
                  :thickness="0.22"
                  :color="item.percentage > 55 ? 'primary' : 'red'"
                >
                  {{ item.percentage }}%
                </q-circular-progress>
                {{ item.account_obj.label }}
              </div>

              <div class="col-1">
                <span
                  tabindex="1"
                  @click="deletePredictionData(item)"
                  @keydown.enter="deletePredictionData(item)"
                  class="cursor-pointer q-ml-sm mt-4"
                  :class="is_view_readonly ? 'disabled' : ''"
                >
                  <Icon icon="mdi:delete" width="22" height="22" />
                  <q-tooltip anchor="bottom right" self="top right">
                    {{ $t('delete_prediction_data_for_this_account') }}
                  </q-tooltip>
                </span>
              </div>
            </template>

            <div class="col-12 q-mb-sm q-mt-sm">
              <q-separator />
            </div>
          </div>
        </template>
      </template>
      <!-- Results END -->

      <q-card-actions align="right">
        <q-btn
          unelevated
          color="primary"
          class="q-mr-sm"
          :label="$t('test')"
          @click="Proceed"
        />
      </q-card-actions>
    </q-expansion-item>
  </div>

  <q-dialog
    v-model="confirm_ledger_account_delete"
    @keydown.esc="confirm_ledger_account_delete = false"
    @hide="confirm_ledger_account_delete = false"
  >
    <q-card>
      <q-card-section
        class="row"
        style="justify-content: center; display: flex"
      >
        <q-avatar icon="warning" color="primary" text-color="white" />
      </q-card-section>

      <q-card-section class="row items-center">
        <span class="q-ml-sm">{{ $t('confirm_ledger_account_delete') }}</span>
      </q-card-section>

      <q-card-actions align="right">
        <f-btn
          appearance="cancel"
          :label="$t('cancel')"
          @click="confirm_ledger_account_delete = false"
        />
        <f-btn
          :label="$t('proceed')"
          class="q-mr-sm"
          @click="deleteSupplierLedgerAccount()"
        />
      </q-card-actions>
    </q-card>
  </q-dialog>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';

import { defineComponent, ref } from 'vue';
import { storeToRefs } from 'pinia';
import { useAutoAccountingStore } from 'src/store/main';
import { autoAccountingApiService } from 'src/services';
import { ApiExceptions } from 'src/exceptions/index';
import type { dynamicObj } from 'src/pages/assets';
import helperMixin from 'src/mixins/helperMixin';
import { objLen, isEmptyString } from 'src/utils/general';
export default defineComponent({
  mixins: [helperMixin],
  props: {},
  
  watch: {
    accounting_mode: {
      handler: function (newVal, oldVal) {
        if (newVal !== oldVal) {
          this.init();
        }
      },
    },
  },
  computed: {
    has_predictions() {
      if (this.accounting_mode === 'total_line') {
        return this.total_line_predictions.length > 0;
      }
      return this.line_items_line_predictions.length > 0;
    },
  },
  mounted: function () {
    this.init();
  },
  methods: {
    init() {
      try {
        if (this.is_view_readonly) {
          return;
        }
        this.testing_data = [];
        this.addEmptyLine();
      } catch (err: any) {}
    },

    addEmptyLine() {
      const basic_item = {
        supplier_name: this.supplier_name,
      } as dynamicObj;

      if (this.accounting_mode !== 'total_line') {
        basic_item['description'] = '';
      }
      this.testing_data.push(basic_item);
    },

    deleteRow(index: number) {
      this.testing_data.splice(index, 1);
    },

    async Proceed() {
      try {
        if (this.is_view_readonly) {
          return;
        }
        if (!this.isValidData()) {
          notify.error(this.$t('missing_supplier_warning'));
          return;
        }
        this.showLoading();
        const line_items = this.getLineItemsForPredictionAccount();
        const data = { line_items: JSON.stringify(line_items) };
        await this.getPredictions(data);

        this.test_clicked = true;
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },

    deletePredictionData(item: dynamicObj) {
      if (this.is_view_readonly) {
        return;
      }
      if (!this.isValidData() || isEmptyString(this.supplier_name)) {
        notify.error(this.$t('missing_supplier_warning'));
        return;
      }
      this.deletionItem = item;
      this.confirm_ledger_account_delete = true;
    },

    async deleteSupplierLedgerAccount() {
      try {
        if (
          this.is_view_readonly ||
          objLen(this.deletionItem) === 0 ||
          isEmptyString(this.supplier_name)
        ) {
          return;
        }
        const data = {
          supplier: this.supplier_name,
          ledger_account: this.deletionItem.account_obj.id,
        } as dynamicObj;

        if (this.deletionItem.hasOwnProperty('description')) {
          data['description'] = this.deletionItem.description;
        }

        this.showLoading();
        const response =
          await autoAccountingApiService.deleteTrainingData(data);
        if (response.success === false) {
          throw { message: response.message };
        }
        await this.Proceed();
        notify.success(this.$t('selected_training_deleted'));
        this.confirm_ledger_account_delete = false;
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },
  },
  setup() {
    const auto_accounting_store = useAutoAccountingStore();
    const {
      total_line_predictions,
      line_items_line_predictions,
      is_view_readonly,
      supplier_name,
      accounting_mode,
      predictions_by_mode,
    } = storeToRefs(auto_accounting_store);
    const { getPredictions, getLineItemsForPredictionAccount, isValidData } =
      auto_accounting_store;

    return {
      isValidData,
      predictions_by_mode,
      getLineItemsForPredictionAccount,
      total_line_predictions,
      line_items_line_predictions,
      getPredictions,
      accounting_mode,
      is_view_readonly,
      supplier_name,
      testing_data: ref([] as dynamicObj[]),
      test_clicked: ref(false),

      deletionItem: ref({} as dynamicObj),
      confirm_ledger_account_delete: ref(false),
    };
  },
});
</script>
<style scoped lang="scss"></style>
