<template>
  <template v-if="!validating">
    <template v-for="(item, index) in validation" :key="index">
      <div class="row full-width">
        <div class="col-12">{{ index }}</div>
      </div>
      <ul class="validation-list">
        <template v-if="item.success_steps.length > 0">
          <li v-for="(success, index) in item.success_steps" :key="index">
            <div class="alert alert-success" role="alert">
              <q-icon name="done" color="green" size="sm"> </q-icon>
              <span v-html="success"> </span>
            </div>
          </li>
        </template>
        <template v-if="item.errors.length > 0">
          <li v-for="(error, index) in item.errors" :key="index">
            <div class="alert alert-danger" role="alert">
              <q-icon name="close" color="red" size="sm"> </q-icon>
              <span v-html="error"></span>
            </div>
          </li>
        </template>
      </ul>
    </template>
  </template>

  <div class="container-svg" v-if="validating">
    <q-spinner-gears color="primary" size="10em" />
  </div>
</template>

<script lang="ts">
import { defineComponent, ref } from 'vue';
import {
  useAutoAccountingStore,
  useAccountingTypeStore,
  usePoMatchStore,
  useSettingStore,
} from 'src/store/main';
import { storeToRefs } from 'pinia';
import type { dynamicObj } from 'src/pages/assets';
import {
  auto_accounting_setting,
  auto_accounting_types_setting,
  auto_accounting_acc_list_name_setting,
  auto_accounting_po_acc_list_name_setting,
  auto_accounting_dimensions_options_setting,
  dimension_general_dropdown_accounting,
} from 'src/constants';
import { hasValue, isUndefinedOrNull } from 'src/utils/general';

export default defineComponent({
  mixins: [],
  props: {},
  components: {},
  data() {
    return {
      auto_accounting_setting,
      auto_accounting_types_setting,
      auto_accounting_acc_list_name_setting,
      auto_accounting_po_acc_list_name_setting,
      auto_accounting_dimensions_options_setting,
      dimension_general_dropdown_accounting,
    };
  },
  mounted: function () {
    this.validate();
  },
  methods: {
    async validate() {
      try {
        this.validating = true;
        if (this.invalidMainSettings()) {
          return;
        }

        if (this.hasPoMatchData()) {
          await this.validatePoAccounts();
        } else {
          await this.validateAccounts();
        }

        await this.validateDimensionsDropdown();
        await this.validateGeneralDimensionDropdown();
      } catch (error: any) {
        const item_name = 'Error';
        this.validation[item_name] = {} as dynamicObj;
        this.validation[item_name].errors = [] as string[];
        this.validation[item_name].errors.push(error.message);
      } finally {
        this.validating = false;
      }
    },

    invalidMainSettings() {
      const errors_list = this.verifyModuleSettings();
      if (errors_list.length > 0) {
        const item_name = this.$t('missing_auto_accounting_settings');
        this.validation[item_name] = {} as dynamicObj;
        this.validation[item_name].errors = [] as string[];
        this.validation[item_name].success_steps = [] as string[];
        errors_list.forEach((error: any) => {
          this.validation[item_name].errors.push(error);
        });
        return true;
      }
      return false;
    },

    async validateDimensionsDropdown() {
      const item_name = 'Dimensions Range Options';
      let server_result = [] as dynamicObj[];
      this.validation[item_name] = {} as dynamicObj;
      this.validation[item_name].errors = [] as string[];
      this.validation[item_name].success_steps = [] as string[];

      this.vertifySettings(
        item_name,
        this.auto_accounting_dimensions_options_setting,
      );
      if (this.validation[item_name].errors.length > 0) {
        return;
      }
      const dimensions_list_name =
        this.user_settings[this.auto_accounting_dimensions_options_setting];

      try {
        server_result = await this.getCacheDataValues(dimensions_list_name);
        const message = this.$t('list_exists').replace(
          '%s',
          dimensions_list_name,
        );
        this.validation[item_name].success_steps.push(message);
      } catch (error) {
        const message = this.$t('master_data_list_not_found').replace(
          '%s',
          dimensions_list_name,
        );
        this.validation[item_name].errors.push(message);
        return;
      }

      if (server_result.length === 0) {
        const message = this.$t(
          'please_check_if_master_data_list_has_data',
        ).replace('%s', dimensions_list_name);
        this.validation[item_name].errors.push(message);
        return;
      } else {
        this.validation[item_name].success_steps.push(this.$t('list_has_data'));
      }

      const data = {} as dynamicObj;
      Object.keys(server_result[0]).forEach((key) => {
        let newKey = key.trim().toLowerCase().replace(/\s+/g, '_');
        data[newKey] = server_result[0][key];
      });
      const list_columns = Object.keys(data);

      const validate_columns = [
        'accounting_identity',
        'accounting_dimension',
        'to_accounting_identity',
        'from_accounting_identity',
        'accounting_dimension',
      ];

      this.generateColumnsValidityMessage(
        list_columns,
        validate_columns,
        item_name,
      );
    },

    async validateGeneralDimensionDropdown() {
      const item_name = 'Dimensions General Options';
      let server_result = [] as dynamicObj[];
      this.validation[item_name] = {} as dynamicObj;
      this.validation[item_name].errors = [] as string[];
      this.validation[item_name].success_steps = [] as string[];

      this.vertifySettings(
        item_name,
        this.dimension_general_dropdown_accounting,
      );
      if (this.validation[item_name].errors.length > 0) {
        return;
      }
      const list_name =
        this.user_settings[this.dimension_general_dropdown_accounting];

      try {
        server_result = await this.getCacheDataValues(list_name);
        const message = this.$t('list_exists').replace('%s', list_name);
        this.validation[item_name].success_steps.push(message);
      } catch (error) {
        const message = this.$t('master_data_list_not_found').replace(
          '%s',
          list_name,
        );
        this.validation[item_name].errors.push(message);
        return;
      }

      if (server_result.length === 0) {
        const message = this.$t(
          'please_check_if_master_data_list_has_data',
        ).replace('%s', list_name);
        this.validation[item_name].errors.push(message);
        return;
      } else {
        this.validation[item_name].success_steps.push(this.$t('list_has_data'));
      }

      const list_columns = Object.keys(server_result[0]);
      const validate_columns = [
        'id',
        'description',
        'dimension',
        'listid',
        'codevalue',
      ];

      this.generateColumnsValidityMessage(
        list_columns,
        validate_columns,
        item_name,
      );
    },

    generateColumnsValidityMessage(
      list_columns: string[],
      validate_columns: string[],
      item_name: string,
    ) {
      const missing_columns = validate_columns.filter(
        (column) => !list_columns.includes(column),
      );

      if (missing_columns.length === 0) {
        let msg = this.$t('list_has_all_columns');
        msg += '<br /><ul>';
        Array.from(validate_columns).forEach((column_name: any) => {
          msg += '<li>' + column_name.replace(/_/g, ' ') + '</li>';
        });
        msg += '</ul>';
        this.validation[item_name].success_steps.push(msg);
        return;
      }

      if (missing_columns.length > 0) {
        let msg = this.$t('list_has_missing_columns');
        msg += '<br /><ul>';
        Array.from(missing_columns).forEach((column_name: any) => {
          msg += '<li>' + column_name.replace(/_/g, ' ') + '</li>';
        });
        msg += '</ul>';
        this.validation[item_name].errors.push(msg);
      }

      const found_columns = validate_columns.filter((column) =>
        list_columns.includes(column),
      );

      if (found_columns.length !== validate_columns.length) {
        let msg = this.$t('list_has_columns');
        msg += '<br /><ul>';
        Array.from(found_columns).forEach((column_name: any) => {
          msg += '<li>' + column_name.replace(/_/g, ' ') + '</li>';
        });
        msg += '</ul>';
        this.validation[item_name].success_steps.push(msg);
      }
    },

    async validatePoAccounts() {
      const item_name = 'Accounts';
      let server_result = [] as dynamicObj[];
      this.validation[item_name] = {} as dynamicObj;
      this.validation[item_name].errors = [] as string[];
      this.validation[item_name].success_steps = [] as string[];
      if (
        !hasValue(
          this.user_settings[this.auto_accounting_po_acc_list_name_setting],
        )
      ) {
        this.validation[item_name].errors.push(
          this.$t('master_data_list_not_found'),
        );
        return;
      }

      this.vertifySettings(
        item_name,
        this.auto_accounting_po_acc_list_name_setting,
      );
      if (this.validation[item_name].errors.length > 0) {
        return;
      }
      const po_accounts_list_name =
        this.user_settings[this.auto_accounting_po_acc_list_name_setting];

      try {
        server_result = await this.getCacheDataValues(po_accounts_list_name);
        const message = this.$t('list_exists').replace(
          '%s',
          po_accounts_list_name,
        );
        this.validation[item_name].success_steps.push(message);
      } catch (error) {
        const message = this.$t('master_data_list_not_found').replace(
          '%s',
          po_accounts_list_name,
        );
        this.validation[item_name].errors.push(message);
        return;
      }

      if (server_result.length === 0) {
        const message = this.$t(
          'please_check_if_master_data_list_has_data',
        ).replace('%s', po_accounts_list_name);
        this.validation[item_name].errors.push(message);
        return;
      } else {
        this.validation[item_name].success_steps.push(this.$t('list_has_data'));
      }

      // vaidate account columns
      const list_columns = Object.keys(server_result[0]);
      const validate_columns = ['id', 'description'];

      this.generateColumnsValidityMessage(
        list_columns,
        validate_columns,
        item_name,
      );
    },

    vertifySettings(item_name: string, setting_name: string) {
      if (!hasValue(this.user_settings[setting_name])) {
        let message = '';
        message += this.$t('please_set_following_setting');
        message += '<ul>';
        message += '<li>' + setting_name + '</li>';
        message += '</ul>';
        this.validation[item_name].errors.push(message);
        return;
      }
    },

    async validateAccounts() {
      const item_name = 'Accounts';
      let server_result = [] as dynamicObj[];
      this.validation[item_name] = {} as dynamicObj;
      this.validation[item_name].errors = [] as string[];
      this.validation[item_name].success_steps = [] as string[];

      this.vertifySettings(
        item_name,
        this.auto_accounting_acc_list_name_setting,
      );
      if (this.validation[item_name].errors.length > 0) {
        return;
      }
      const accounts_list_name =
        this.user_settings[this.auto_accounting_acc_list_name_setting];

      try {
        server_result = await this.getCacheDataValues(accounts_list_name);
        const message = this.$t('list_exists').replace(
          '%s',
          accounts_list_name,
        );
        this.validation[item_name].success_steps.push(message);
      } catch (error) {
        const message = this.$t('master_data_list_not_found').replace(
          '%s',
          accounts_list_name,
        );
        this.validation[item_name].errors.push(message);
        return;
      }

      if (server_result.length === 0) {
        const message = this.$t(
          'please_check_if_master_data_list_has_data',
        ).replace('%s', accounts_list_name);
        this.validation[item_name].errors.push(message);
        return;
      } else {
        this.validation[item_name].success_steps.push(this.$t('list_has_data'));
      }

      // vaidate account columns
      const list_columns = Object.keys(server_result[0]);
      const validate_columns = [
        'id',
        'dimensionprofile',
        'nominalaccount',
        'description',
      ];

      this.generateColumnsValidityMessage(
        list_columns,
        validate_columns,
        item_name,
      );
    },
  },
  setup() {
    const accounting_type_store = useAccountingTypeStore();
    const { verifyModuleSettings } = accounting_type_store;

    const po_match_store = usePoMatchStore();
    const { hasPoMatchData } = po_match_store;

    const auto_accounting_store = useAutoAccountingStore();
    const { getCacheDataValues } = auto_accounting_store;

    const settings_store = useSettingStore();
    const { user_settings } = storeToRefs(settings_store);

    return {
      hasPoMatchData,
      getCacheDataValues,
      verifyModuleSettings,
      user_settings,
      validation: ref({} as dynamicObj),
      validating: ref(false),
    };
  },
});
</script>
<style scoped lang="scss">
.validation-list {
  list-style-type: none;
}

.container-svg {
  display: flex;
  justify-content: center;
  align-items: center;
  height: 200px;
}
</style>
