<script lang="ts">
import { notify } from 'src/components/notifications/notify';

import { useImageAuth } from 'src/composables/useImageAuth';
import { storeToRefs } from 'pinia';
import stringUtil from 'src/utils/string';
import { defineComponent, ref } from 'vue';
import { DOC2API_URL } from 'src/pages/APIs';
import type { dynamicObj } from 'src/pages/assets';
import documentUtil from 'src/utils/documentUtil';
import { ApiExceptions } from 'src/exceptions/index';
import MessageBanner from 'src/components/MessageBanner.vue';
import SidebarPanel from 'src/components/document/SidebarPanel.vue';
import SidebarActionButtons from 'src/components/document/SidebarActionButtons.vue';
import DocumentFooter from 'src/components/document/DocumentFooter.vue';
import { useSidebarPanel } from 'src/composables/useSidebarPanel';
import ErrorDocumentView from 'src/pages/Errors/ErrorDocumentView.vue';

import {
  usePoMatchStore,
  useDocLockStore,
  useDocumentStore,
  useAccountingTypeStore,
  useAutoAccountingStore} from 'src/store/main';

import { copyToClipboard } from 'quasar';
import type { QBtnToggleProps } from 'quasar';
import Loader from 'src/components/Loader.vue';
import helperMixin from 'src/mixins/helperMixin';
import { mdiShare } from '@quasar/extras/mdi-v6';
import { readOnlyDocStatus } from 'src/constants';
import SaveBtn from './Detail/components/SaveBtn.vue';
import ProceedBtn from './Detail/components/ProceedBtn.vue';
import ExpertMode from './Detail/components/ExpertMode.vue';
import SectionAutoAccounting from './SectionAutoAccounting.vue';
import PredictionBtn from './Detail/components/predictionBtn.vue';
import SubHeader from 'src/pages/Settings/Components/Sub-Header.vue';
import SetupValidation from './Detail/components/SetupValidation.vue';
import timeSpentTimer from 'src/components/document/timeSpentTimer/main.vue';

export default defineComponent({
  el: '#app',
  mixins: [stringUtil, helperMixin, documentUtil],
  components: {
    
    Loader,
    SaveBtn,
    SubHeader,
    ExpertMode,
    ProceedBtn,
    PredictionBtn,
    MessageBanner,
    SidebarPanel,
    SidebarActionButtons,
    DocumentFooter,
    SetupValidation,
    ErrorDocumentView,
    SectionAutoAccounting,
    timeSpentTimer,
  },
  watch: {
    accounting_error: {
      handler: function (newVal, oldVal) {
        if (newVal !== '') {
          this.is_view_readonly = true;
          return;
        }
        this.is_view_readonly = false;
      },
    },
    processing: {
      handler: function (newVal, oldVal) {
        if (newVal == true) {
          this.showLoading();
        } else {
          this.hideLoading();
        }
      },
    },

    data_loaded: {
      handler: function (newVal, oldVal) {
        if (newVal == true) {
          this.hideLoading();
        } else {
          this.showLoading();
        }
      },
    },

    has_fetch_error: {
      handler: function (newVal, oldVal) {
        if (newVal == true) {
          this.hideLoading();
        } else {
          this.showLoading();
        }
      },
    },
  },
  mounted() {
    this.init();
  },

  data() {
    return {};
  },
  computed: {
    accounting_mode_options_typed(): QBtnToggleProps['options'] {
      return this.accounting_mode_options as QBtnToggleProps['options'];
    },
  },
  beforeRouteLeave: async function (to: any, from: any, next: any) {
    this.resetDocStore(to.fullPath);
    this.resetAccountingStore();
    this.resetAccountingTypeStore();
    await this.releaseDocLock({ doc_id: this.docId });
    const po_match_store = usePoMatchStore();
    po_match_store.$reset();
    if (typeof this.missing_supplier_warning === 'function') {
      this.missing_supplier_warning();
    }

    next();
  },
  methods: {
    init() {
      try {
        this.docId = this.$route.params.id as string;

        this.showLoading();
        this.accounting_error = '';
        (<any>window).acc = this;
        this.handleReadOnlyView();
        this.handleMode();
        this.data_loaded = true;
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
        this.accounting_error = msg;
      } finally {
        //this.processing = false;
        this.hideLoading();
      }
    },

    verifyUserSettings() {
      this.setup_error = false;
      const errors_list = this.verifyModuleSettings();
      if (errors_list.length > 0) {
        this.setup_error = true;
        throw new Error(this.$t('missing_auto_accounting_settings'));
      }
    },

    handleReadOnlyView() {
      this.is_view_readonly = false;
      if (readOnlyDocStatus.includes(this.record.status)) {
        this.is_view_readonly = true;
      }
    },

    hasPendingPoMatch() {
      try {
        let pendingAmount = parseFloat(
          this.pending_amount.replace(/[^0-9]/g, ''),
        );
        if (
          this.pending_amount &&
          this.pending_amount != '' &&
          pendingAmount > 0
        ) {
          return true;
        }
        return false;
      } catch (err) {
        logError(err);
        return true;
      }
    },

    copyURL() {
      if (this.doc_url.trim().length > 0) {
        copyToClipboard(this.doc_url).then(() => {
          notify.success(this.$t('link_copied_to_clipboard'));
        });
      }
    },

    closeDialog(e: any) {
      this.empty_line_item = false;
    },

    handleMode() {
      let type = 'total_line_item';
      if (this.accounting_mode === 'total_line') {
        type = 'line_item';
      }

      this.disableLineItems(type);
      // `type` is the now-inactive row type that disableLineItems just cleared;
      // the active type is the other one. Switching back re-activates rows whose
      // dimensions were cleared on a prior switch — re-derive them from the
      // account so saved/relevant dimensions reappear. Restrict to the active
      // type so the row we just intentionally cleared is not re-filled.
      const active_type = type === 'line_item' ? 'total_line_item' : 'line_item';
      this.loadMissingDimensions(active_type);
      this.calculateTotalByMode();
    },

    disableLineItems(type = 'line_item') {
      Array.from(this.lineItems).forEach((row: any, index: any) => {
        row.error = '';
        if (row.type === type) {
          row.readonly = true;
          row.split_items = [];
          row.dimensions = [];
        } else {
          row.readonly = false;
        }
      });
    },

    toggleExpertMode() {
      if (this.is_view_readonly) {
        return;
      }
      this.toggleSideBar('expert_mode');
    },
    openImageInSeparateWindow() {
      const route = this.$router.resolve({ path: '/po-image' });
      window.open(
        route.href,
        '_blank',
        'toolbar=yes,scrollbars=yes,resizable=yes,left=500,width=1000,height=1000',
      );
    },
    onZoomChange(val: number) {
      this.imageZoom = val;
    },
    currentPage() {
      return this.page;
    },
    scrollToPage(pageNum: any) {
      const num = parseInt(pageNum);
      if (!num || num < 1 || !this.record.images || num > this.record.images.length) {
        return;
      }
      this.page = num;
    },
    validatePageNumber() {
      if (!this.page || this.page < 1) {
        this.page = 1;
      }
      if (this.record.images && this.page > this.record.images.length) {
        this.page = this.record.images.length;
      }
      this.scrollToPage(this.page);
    },
    prevPage() {
      if (this.page <= 1) return;
      this.page--;
    },
    nextPage() {
      if (!this.record.images || this.page >= this.record.images.length) return;
      this.page++;
    },
    reloadAccounts() {
      const custom_event = new CustomEvent('reload_accounts', {});
      document.dispatchEvent(custom_event);
    },
  },
  setup() {
    const doc_store = useDocumentStore();
    doc_store.$reset();
    const {
      record,
      bannerBg,
      error: has_fetch_error,
      processing,
      hasApiData,
    } = storeToRefs(doc_store);
    const { resetDocStore, isPurchaseInvoice } = doc_store;

    const auto_accounting_store = useAutoAccountingStore();
    const {
      resetAccountingStore,
      calculateTotalByMode,
      loadMissingDimensions,
    } = auto_accounting_store;

    const {
      lineItems,
      dimensions,
      expert_mode,
      accounting_mode,
      accounts_loaded,
      is_view_readonly,
      amountFieldsList,
      accounting_error,
      accounting_mode_options,
    } = storeToRefs(auto_accounting_store);

    const po_match_store = usePoMatchStore();

    const { pending_amount } = storeToRefs(po_match_store);

    const accounting_type_store = useAccountingTypeStore();
    const { view_types } = storeToRefs(accounting_type_store);
    const {
      verifyModuleSettings,
      resetAccountingTypeStore,
      getbaseTotalLineItem,
    } = accounting_type_store;

    const doc_lock_store = useDocLockStore();
    const { releaseDocLock } = doc_lock_store;

    const { tokenQueryParam, refreshTokenParam } = useImageAuth();
    const { current_sidebar, sidebarWidthClass, rightSectionClass, toggleSideBar } = useSidebarPanel();
    return {
      current_sidebar,
      sidebarWidthClass,
      rightSectionClass,
      toggleSideBar,
      page: ref(1),
      imageZoom: ref(1),
      baseUrl: DOC2API_URL,
      resetDocStore,
      releaseDocLock,
      hasApiData,
      isPurchaseInvoice,
      resetAccountingStore,
      verifyModuleSettings,
      calculateTotalByMode,
      loadMissingDimensions,
      getbaseTotalLineItem,
      resetAccountingTypeStore,
      tokenQueryParam,
      accounts_loaded,
      accounting_error,
      amountFieldsList,
      pending_amount,
      dimensions,
      accounting_mode,
      is_view_readonly,
      bannerBg,
      lineItems,
      view_types,
      has_fetch_error,
      error_message: ref(''), // error message for view
      record,
      processing,
      docId: ref(''),
      splitterModel: ref(70), // start at 50%
      empty_line_item: ref(false),
      doc_url: ref(''),
      data_loaded: ref(false),
      accounting_mode_options,
      show_setup_validation: ref(false),
      disable_mode: ref(false),
      //supplier_name,
      expert_mode,
      missing_supplier_warning: {} as any,
      setup_error: ref(false),
      mdiShare,
    };
  },
});
</script>

