import type { dynamicObj } from 'src/pages/assets';

export default {
  validate: function (value: string, ranges: dynamicObj[]) {
    let is_valid = false;

    value = value.trim();
    for (const range of ranges) {
      if (value >= range.start && value <= range.end) {
        is_valid = true;
      }
    }
    return is_valid;
  },
};
