<template>
  <q-card style="width: 800px; max-width: 1060px">
    <q-toolbar class="secondary-toolbar">
      <q-toolbar-title>
        <span class="text-weight-bold primary-bg-text">{{
          $t('accounts')
        }}</span>
      </q-toolbar-title>

      <q-btn
        flat
        round
        dense
        class="primary-bg-text"
        icon="close"
        @click="closeDialog"
      />
    </q-toolbar>

    <q-card-section>
      <div class="row items-center q-mb-sm">
        <div class="q-ml-auto q-mr-auto">
          <q-avatar square size="40px">
            <Icon icon="mdi:auto-fix" width="40" height="40" />
          </q-avatar>
        </div>
      </div>

      <div class="row q-pl-sm q-pt-sm q-pb-sm table-header">
        <div class="col-2 flex items-center justify-left">
          {{ $t('position') }}
        </div>

        <div class="col-9 flex items-center justify-left">
          {{ $t('accounts') }}
        </div>

        <div class="col-1"></div>
      </div>

      <template v-if="predictions_by_mode.length === 0">
        <div class="row q-pl-sm q-pt-sm total-line-item-area">
          <div class="col-12 flex flex-center">
            {{ $t('no_predictions_found') }}
          </div>
        </div>
      </template>

      <template v-for="(items, name) in predictions_by_mode" :key="name">
        <div class="row q-pl-sm q-pt-sm">
          <div class="col-12 flex items-center justify-left">
            <span>
              {{ name }}
            </span>
          </div>
        </div>

        <div class="row pl-20">
          <template v-for="(item, index) in items" :key="item">
            <div class="col-6 q-mb-sm">
              <div class="row">
                <div class="col-10 flex items-center justify-left">
                  <q-checkbox
                    v-model="item.checked"
                    :label="item.account_obj.label"
                    :key="index + '_' + item.account_obj.value"
                  />
                </div>

                <div class="col-1">
                  <q-circular-progress
                    show-value
                    font-size="12px"
                    :value="item.percentage ? Number(item.percentage) : 0"
                    size="40px"
                    :thickness="0.22"
                    :color="item.percentage > 55 ? 'primary' : 'red'"
                  >
                    {{ item.percentage }}%
                  </q-circular-progress>
                </div>
              </div>
            </div>
          </template>
        </div>
        <q-separator class="q-mt-sm" />
      </template>
    </q-card-section>

    <q-card-actions align="right">
      <f-btn appearance="cancel" :label="$t('cancel')" @click="closeDialog" />
      <f-btn
        class="float-right btns"
        :label="$t('proceed')"
        v-if="!is_view_readonly"
        @click="proceed()"
      />
    </q-card-actions>
  </q-card>
</template>

<script lang="ts">

import { defineComponent } from 'vue';
import { storeToRefs } from 'pinia';
import { useAutoAccountingStore } from 'src/store/main';
import type { dynamicObj } from 'src/pages/assets';

export default defineComponent({
    props: {},
  
  watch: {},
  emits: ['itemSelected', 'cleanupOnhide'],
  computed: {},
  mounted() {
    // (<any>window).accp = this;
  },
  methods: {
    proceed() {
      this.saveSelections();
      this.closeDialog();
    },

    saveSelections() {
      for (let [name, items] of Object.entries(this.predictions_by_mode)) {
        const row = {} as dynamicObj;
        const items = this.predictions_by_mode[name];
        let selected = [] as dynamicObj[];

        for (const [index, item] of items.entries()) {
          if (item.checked) {
            item.checked = false;
            selected.push(item);
          }
        }

        if (selected.length === 0) {
          continue;
        }

        const line_index = items[0].line_index;
        this.updateAccountInStore(line_index, null, {});
        this.lineItems[line_index].split_items = [];

        if (selected.length === 1) {
          this.updateAccountInStore(line_index, null, selected[0].account_obj);
        }

        if (selected.length > 1) {
          this.makeSplittedLineItems(selected, line_index);
        }
      }
    },

    makeSplittedLineItems(selected: dynamicObj[], pred_index: number) {
      for (const [index, item] of selected.entries()) {
        const line = this.baseSplitLineItem();
        line.percentage = '0%';
        this.lineItems[pred_index].split_items.push(line);
        this.updateAccountInStore(pred_index, index, item.account_obj);
      }
      this.autFillEmptyLineItems(pred_index);
    },

    closeDialog() {
      this.$emit('cleanupOnhide');
    },
  },
  setup() {
    const auto_accounting_store = useAutoAccountingStore();
    const {
      is_view_readonly,
      total_line_predictions,
      line_items_line_predictions,
      accounting_mode,
      lineItems,
      predictions_by_mode,
      prediction_selections,
    } = storeToRefs(auto_accounting_store);

    const {
      updateAccount: updateAccountInStore,
      hasTotalPredictions,
      hasLineItemsPredictions,
      getTotalLineIndex,
      baseSplitLineItem,
      autFillEmptyLineItems,
    } = auto_accounting_store;

    return {
      is_view_readonly,
      predictions_by_mode,
      updateAccountInStore,
      autFillEmptyLineItems,
      baseSplitLineItem,
      lineItems,
      getTotalLineIndex,
      hasTotalPredictions,
      hasLineItemsPredictions,
      accounting_mode,
      total_line_predictions,
      line_items_line_predictions,
      prediction_selections,
    };
  },
});
</script>
<style scoped lang="scss"></style>
