<template>
  <!-- template view LN OR M3-->
  <template v-if="view_template !== ''">
    <component :is="view_template" :currentView="view_template"> </component>
  </template>
  <template v-else>
    <template v-for="(item, index) in validation" :key="index">
      <div class="row full-width">
        <div class="col-12">{{ index }}</div>
      </div>
      <ul class="validation-list">
        <template v-if="item.success_steps.length > 0">
          <li v-for="(success, index) in item.success_steps" :key="index">
            <div class="alert alert-success" role="alert">
              <q-icon name="done" color="green" size="sm"> </q-icon>
              <span v-html="success"> </span>
            </div>
          </li>
        </template>
        <template v-if="item.errors.length > 0">
          <li v-for="(error, index) in item.errors" :key="index">
            <div class="alert alert-danger" role="alert">
              <q-icon name="close" color="red" size="sm"> </q-icon>
              <span v-html="error"></span>
            </div>
          </li>
        </template>
      </ul>
    </template>
  </template>
</template>

<script lang="ts">
import { defineComponent, ref } from 'vue';
import { useAccountingTypeStore } from 'src/store/main';
import { storeToRefs } from 'pinia';
import LN_VIEW from 'src/pages/AutoAccounting/Detail/Templates/LN/SetupValidation.vue';
import M3_VIEW from 'src/pages/AutoAccounting/Detail/Templates/M3/SetupValidation.vue';
import type { dynamicObj } from 'src/pages/assets';

export default defineComponent({
  mixins: [],
  props: {},
  components: {
    LN_VIEW,
    M3_VIEW,
  },
  watch: {
    view_template: {
      handler: function (newVal, oldVal) {
        this.verifyBasicValidation();
      },
    },
  },
  mounted() {
    this.verifyBasicValidation();
  },
  methods: {
    verifyBasicValidation() {
      if (this.view_template !== '') {
        return;
      }
      if (this.invalidMainSettings()) {
        return;
      }
    },
    invalidMainSettings() {
      const errors_list = this.verifyModuleSettings();
      if (errors_list.length > 0) {
        const item_name = this.$t('missing_auto_accounting_settings');
        this.validation[item_name] = {} as dynamicObj;
        this.validation[item_name].errors = [] as string[];
        this.validation[item_name].success_steps = [] as string[];
        errors_list.forEach((error: any) => {
          this.validation[item_name].errors.push(error);
        });
        return true;
      }
      return false;
    },
  },
  setup() {
    const accounting_type_store = useAccountingTypeStore();
    const { verifyModuleSettings } = accounting_type_store;
    const { view_template } = storeToRefs(accounting_type_store);

    return {
      verifyModuleSettings,
      view_template,
      validation: ref({} as dynamicObj),
    };
  },
});
</script>
