<template>
  <f-btn
    class="q-ml-sm predictionIcon"
    :class="!is_view_readonly ? '' : ' disabled '"
    @click="showPredictions"
    :disable="!accounts_loaded || account_predictions.length == 0"
  >
    <Icon icon="mdi:auto-fix" width="20" height="20" />
    <q-tooltip>
      <template v-if="!predictionsLoaded">
        {{ $t('preparing_prediction_data') }}
      </template>
      <template v-else-if="account_predictions.length == 0">
        {{ $t('no_prediction_data_found') }}
      </template>
      <template v-else>
        {{ $t('show_predictions') }}
      </template>
    </q-tooltip>
  </f-btn>

  <q-dialog
    v-model="show_popup"
    @keydown.esc="cleanupOnhide"
    @hide="cleanupOnhide"
  >
    <PredictionPopup
      :show_popup="show_popup"
      @cleanupOnhide="cleanupOnhide"
    ></PredictionPopup>
  </q-dialog>
</template>

<script lang="ts">

import { defineComponent, ref } from 'vue';
import { storeToRefs } from 'pinia';
import { useAutoAccountingStore } from 'src/store/main';
import PredictionPopup from './predictionPopup.vue';

export default defineComponent({
    props: {},
  components: {
    
    PredictionPopup,
  },
  watch: {},
  computed: {},
  methods: {
    showPredictions() {
      this.show_popup = true;
    },

    cleanupOnhide() {
      this.show_popup = false;
    },
  },
  setup() {
    const auto_accounting_store = useAutoAccountingStore();
    const {
      is_view_readonly,
      accounts_loaded,
      account_predictions,
      predictionsLoaded,
    } = storeToRefs(auto_accounting_store);

    return {
      accounts_loaded,
      is_view_readonly,
      predictionsLoaded,
      account_predictions,
      show_popup: ref(false),
    };
  },
});
</script>
<style scoped lang="scss"></style>
