<template>
  <q-btn
    unelevated
    class="bg-primary text-white"
    tabindex="1"
    @click="onProceed"
    :label="$t('proceed')"
    :disabled="is_view_readonly || !accounts_loaded"
  >
    <q-spinner
      v-if="!accounts_loaded"
      size="20px"
      color="white"
      class="q-mr-xs"
    />
  </q-btn>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import axios from 'axios';
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import type { dynamicObj } from 'src/pages/assets';
import helperMixin from 'src/mixins/helperMixin';
import { isEmptyString } from 'src/utils/general';
import validateRange from '../utils/validateRange';
import { ApiExceptions } from 'src/exceptions/index';
import { removeNonNumeric } from 'src/utils/validateRegex';
import {
  useDocumentStore,
  useAutoAccountingStore,
  useSettingStore,
} from 'src/store/main';
import cache from 'src/utils/cache';
export default defineComponent({
  mixins: [helperMixin, cache],
  watch: {},
  data() {
    return {};
  },
  computed: {},
  methods: {
    async onProceed() {
      try {
        if (this.is_view_readonly || !(await this.validateForm())) {
          return;
        }

        this.showLoading();
        await this.callExportApi();
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },

    prepareJsonForSave() {
      // save line items and header line item
      this.record.accounting = {
        mode: this.accounting_mode,
        line_items: this.prepareDimensionsValues(),
      };
    },

    // this function is only written to prepare data for Pfaudler Group (DPG-96)
    // there dimensions contains '_' so need to send only string which comes after '_'
    prepareDimensionsValues(): any {
      const lineItems = JSON.parse(JSON.stringify(this.lineItems));

      for (let item of lineItems) {
        if (item.split_items && item.split_items.length > 0) {
          for (let splitItems of item.split_items) {
            this.processDimensions(splitItems);
          }

          continue;
        }

        this.processDimensions(item);
      }
      return lineItems;
    },
    processDimensions(item: any) {
      const delimiter = '_';

      if (!item.dimensions || item.dimensions.length == 0) {
        return;
      }

      for (let dimensions of item.dimensions) {
        if (!dimensions.value || !dimensions.value.includes(delimiter)) {
          continue;
        }

        let result = dimensions.value.split(delimiter);

        dimensions.value = result[1];
      }
    },
    async validateForm() {
      let is_valid = true;
      try {
        if (!this.lineItems || this.lineItems.length == 0) {
          is_valid = false;
          notify.error(this.$t('please_check_some_values_are_missing'));
        }

        this.clearErrors(this.lineItems);
        const is_dimensions_valid = this.validateLineItemDimensions(
          this.lineItems,
        );
        const is_amount_valid = await this.validateAmounts();
        const is_account_valid = this.validateAccounts();
        const is_booking_reference_valid = this.validateAdditionalFields(
          this.lineItems,
        );

        if (
          !is_dimensions_valid ||
          !is_amount_valid ||
          !is_account_valid ||
          !is_booking_reference_valid
        ) {
          is_valid = false;
          notify.error(this.$t('please_check_some_values_are_missing'));
        }
      } catch (err) {
        logError(err);
      }

      return is_valid;
    },

    clearErrors(line_items: Array<dynamicObj>) {
      for (const [index, item] of line_items.entries()) {
        this.clearLineItemErrors(item);
        if (
          !(item.hasOwnProperty('split_items') && item.split_items.length > 0)
        ) {
          continue;
        }
        for (const [index, split_item] of item.split_items.entries()) {
          this.clearErrors(item.split_items);
        }
      }
    },

    clearLineItemErrors(line_item: dynamicObj) {
      if (line_item.hasOwnProperty('account_error')) {
        line_item.account_error = '';
      }
      if (line_item.hasOwnProperty('amount_error')) {
        line_item.amount_error = '';
      }
      if (line_item.hasOwnProperty('error')) {
        line_item.error = '';
      }
      if (line_item.hasOwnProperty('additional_field_error')) {
        line_item.additional_field_error = '';
      }
    },

    validateLineItemDimensions(line_items: Array<dynamicObj>) {
      let is_valid = true;

      for (const [index, item] of line_items.entries()) {
        if (!item.account) {
          item.dimensions = [];
        }

        if (item.dimensions && item.dimensions.length > 0) {
          const is_valid_for_each = this.validateDimensionForEach(
            item.dimensions,
            item.account,
          );
          if (!is_valid_for_each) {
            is_valid = false;
          }
        }

        if (item.hasOwnProperty('split_items') && item.split_items.length > 0) {
          const is_splited_valid = this.validateLineItemDimensions(
            item.split_items,
          );
          if (!is_splited_valid) {
            is_valid = false;
          }
        }
      }

      return is_valid;
    },

    validateAdditionalFields(line_items: Array<dynamicObj>) {
      let is_valid = true;

      const valid_booking_reference = this.user_settings[
        'AUTO_ACCOUNTING_FIELDS'
      ] as string;
      // disable for now until booking_reference is deleted from the prefernce as it is hard coded now
      if (true || !valid_booking_reference) {
        return is_valid;
      }

      const storedConfig = JSON.parse(valid_booking_reference);
      // const fieldsConfig = JSON.parse(storedConfig.value);

      storedConfig.forEach((fieldConfig: any) => {
        if (!fieldConfig.validation_rules) return;

        const fieldName = fieldConfig.field_name;
        const isRequiredRule = fieldConfig.validation_rules.find(
          (rule: any) => rule.rule === 'is_required',
        );

        line_items.forEach((item: any) => {
          if (this.accounting_mode === 'total_line') {
            if (item.type !== 'total_line_item') {
              return;
            }
          }
          if (item.hasOwnProperty(fieldName)) {
            if (item.split_items && item.split_items.length > 0) {
              item.split_items.forEach((split_item: any) => {
                if (isRequiredRule && isRequiredRule.value === true) {
                  if (
                    !split_item[fieldName] ||
                    split_item[fieldName].trim().length === 0
                  ) {
                    if (!split_item.additional_field_error) {
                      split_item.additional_field_error = [];
                    }
                    split_item.additional_field_error.push({
                      field: fieldName,
                      error: this.$t('required'),
                    });
                    is_valid = false;
                  }
                }
              });
            } else {
              if (isRequiredRule && isRequiredRule.value === true) {
                if (!item[fieldName] || item[fieldName].trim().length === 0) {
                  if (!item.additional_field_error) {
                    item.additional_field_error = [];
                  }
                  item.additional_field_error.push({
                    field: fieldName,
                    error: this.$t('required'),
                  });
                  is_valid = false;
                }
              }
            }
          }
        });
      });

      return is_valid;
    },

    validateDimensionForEach(
      dimensions: Array<dynamicObj>,
      account: dynamicObj,
    ) {
      let is_valid = true;
      Array.from(dimensions).forEach((row: any, index: any) => {
        row.error = '';
        const rules = this.getDimensionRules(account.id, row.id);
        if (row.rule.toLowerCase() == 'm' && row.value.trim().length === 0) {
          row.error = this.buildRangeErrorMessage(rules, true);
          is_valid = false;
        } else if (
          rules.length > 0 &&
          row.value.trim().length !== 0 &&
          validateRange.validate(row.value, rules) === false
        ) {
          row.error = this.buildRangeErrorMessage(rules);
          is_valid = false;
        }
      });
      return is_valid;
    },

    getDimensionRules(account: string, dimension_id: string) {
      if (
        !this.dimension_rules.hasOwnProperty(account) ||
        !this.dimension_rules[account].hasOwnProperty(dimension_id)
      ) {
        return [] as dynamicObj[];
      }

      return this.dimension_rules[account][dimension_id] as dynamicObj[];
    },

    buildRangeErrorMessage(rules: Array<dynamicObj>, required = false) {
      let message = '';
      if (required) {
        message = this.$t('required');
      }

      if (rules.length === 0) {
        return message;
      }

      message = isEmptyString(message) ? '' : ' - ' + message + '<br />';
      message += 'Please add a value within one of the following ranges:<br />';
      for (const [index, rule] of rules.entries()) {
        let start = rule.start.toString() as string;
        let end = rule.end.toString() as string;
        if (start === end) {
          message += ` - ${start}<br />`;
        } else {
          message += ` - From "${start}" to "${end}"<br />`;
        }
      }

      return message;
    },

    validateAccounts() {
      const line_items = this.getSelectedModeLineItems();
      return this.validateLineItemsAccounts(line_items);
    },

    getSelectedModeLineItems() {
      if (this.accounting_mode === 'total_line') {
        const line_items = this.lineItems.filter(
          (v: any) => v.type.toLowerCase() === 'total_line_item',
        );
        return line_items;
      }

      const line_items = this.lineItems.filter((v: any) => {
        return v.type.toLowerCase() === 'line_item';
      });
      return line_items;
    },

    validateLineItemsAccounts(lineItems: Array<dynamicObj>) {
      let is_valid = true;
      Array.from(lineItems).forEach((line_item: any, index: any) => {
        if (
          line_item.hasOwnProperty('split_items') &&
          line_item.split_items.length > 0
        ) {
          const is_splited_valid = this.validateLineItemsAccounts(
            line_item.split_items,
          );
          if (!is_splited_valid) {
            is_valid = false;
          }
        } else {
          if (!line_item.account) {
            line_item.account_error = this.$t('required');
            is_valid = false;
          }
        }
      });
      return is_valid;
    },

    async validateAmounts() {
      if (!this.isMultiTaxSection) {
        return await this.validateLineItemAmount();
      }

      await this.calculateTotalByMode();
      let is_valid = true;

      for (const [index, item] of this.lineItems.entries()) {
        const is_equal = await this.checkTotalForEachLineItem(item);
        if (!is_equal) {
          is_valid = false;
          item.error = this.$t(
            'line_item_total_not_equal_to_line_item_split_total',
          );
        }
      }
      return is_valid;
    },

    async validateLineItemAmount() {
      let is_valid = true;
      await this.calculateTotalByMode();
      const total_line_index = this.getTotalLineIndex();
      if (total_line_index === -1) {
        return false;
      }

      const total_line_item = this.lineItems[total_line_index];
      if (parseFloat(removeNonNumeric(total_line_item.pending_amount)) > 0) {
        is_valid = false;
        total_line_item.error = this.$t('total_amount_not_equal_to_line_items');
      }

      if (this.accounting_mode === 'total_line') {
        return is_valid;
      }
      //
      for (const [index, item] of this.lineItems.entries()) {
        if (item.type === 'total_line_item') {
          continue;
        }
        const is_equal = await this.checkTotalForEachLineItem(item);
        if (!is_equal) {
          is_valid = false;
          item.error = this.$t(
            'line_item_total_not_equal_to_line_item_split_total',
          );
        }
      }
      return is_valid;
    },

    async callExportApi() {
      try {
        this.prepareJsonForSave();
        this.showLoading();
        const response = await this.exportDocument(this.record.doc_id);
        if (response.success === false) {
          throw { message: response.message };
        }
        notify.success(this.$t('MSG_SAVE'));
        this.is_view_readonly = true;
        if (response.success === true) {
          this.$router.push('/dashboard');
          return;
        }

        notify.error(response.data.message);
        this.record = response.data;
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },
  },
  setup() {
    const doc_store = useDocumentStore();
    const { record } = storeToRefs(doc_store);
    const { saveDocument, exportDocument } = doc_store;

    const auto_accounting_store = useAutoAccountingStore();
    const {
      lineItems,
      is_view_readonly,
      accounting_mode,
      dimension_rules,
      isMultiTaxSection,
      accounts_loaded,
    } = storeToRefs(auto_accounting_store);
    const {
      calculateTotalByMode,
      getTotalLineIndex,
      checkTotalForEachLineItem,
    } = auto_accounting_store;

    const settings_store = useSettingStore();
    const { user_settings } = storeToRefs(settings_store);

    return {
      saveDocument,
      exportDocument,
      getTotalLineIndex,
      calculateTotalByMode,
      checkTotalForEachLineItem,
      record,
      lineItems,
      user_settings,
      accounts_loaded,
      accounting_mode,
      dimension_rules,
      is_view_readonly,
      isMultiTaxSection,
    };
  },
});
</script>
<style scoped lang="scss"></style>
