<template>
  <div class="row full-width q-mb-sm" v-if="!is_view_readonly">
    <div class="col-4">
      <q-btn
        class="bg-primary text-white"
        unelevated
        tabindex="1"
        @click="confirm_all_training_delete = true"
        :label="$t('delete_all')"
        :disabled="is_view_readonly"
      >
        <q-tooltip class="bg-red" anchor="bottom right" self="top right">
          {{ $t('delete_all_training_for_this_org') }}
        </q-tooltip>
      </q-btn>
    </div>

    <div class="col-8">
      <q-btn
        class="bg-primary text-white q-mr-sm"
        unelevated
        tabindex="1"
        @click="confirm_supplier_training_delete = true"
        :label="$t('delete_supplier_training')"
        :disabled="is_view_readonly"
      >
        <q-tooltip class="bg-red" anchor="bottom right" self="top right">
          {{ $t('delete_current_supplier_training') }}
        </q-tooltip>
      </q-btn>
    </div>
  </div>

  <div class="fixed-height-div scrolle-y">
    <TrainingModel />

    <TestModel />
  </div>

  <q-dialog
    v-model="confirm_all_training_delete"
    @keydown.esc="confirm_all_training_delete = false"
    @hide="confirm_all_training_delete = false"
  >
    <q-card>
      <q-card-section
        class="row"
        style="justify-content: center; display: flex"
      >
        <q-avatar icon="warning" color="primary" text-color="white" />
      </q-card-section>

      <q-card-section class="row items-center">
        <span class="q-ml-sm">{{ $t('confirm_all_training_delete') }}</span>
      </q-card-section>

      <q-card-actions align="right">
        <f-btn
          appearance="cancel"
          :label="$t('cancel')"
          v-close-popup
          @click="confirm_all_training_delete = false"
        />
        <f-btn
          :label="$t('proceed')"
          class="q-mr-sm"
          @click="deleteAllTrainings()"
        />
      </q-card-actions>
    </q-card>
  </q-dialog>

  <q-dialog
    v-model="confirm_supplier_training_delete"
    @keydown.esc="confirm_supplier_training_delete = false"
    @hide="confirm_supplier_training_delete = false"
  >
    <q-card>
      <q-card-section
        class="row"
        style="justify-content: center; display: flex"
      >
        <q-avatar icon="warning" color="primary" text-color="white" />
      </q-card-section>

      <q-card-section class="row items-center">
        <span class="q-ml-sm">{{
          $t('confirm_supplier_training_delete')
        }}</span>
      </q-card-section>

      <q-card-actions align="right">
        <f-btn
          appearance="cancel"
          :label="$t('cancel')"
          @click="confirm_supplier_training_delete = false"
        />
        <f-btn
          :label="$t('proceed')"
          class="q-mr-sm"
          @click="deleteCurrentSupplierTraining()"
        />
      </q-card-actions>
    </q-card>
  </q-dialog>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { defineComponent, ref } from 'vue';
import { storeToRefs } from 'pinia';
import { useAutoAccountingStore } from 'src/store/main';
import { autoAccountingApiService } from 'src/services';
import { ApiExceptions } from 'src/exceptions/index';
import { isEmptyString } from 'src/utils/general';
import type { dynamicObj } from 'src/pages/assets';
import helperMixin from 'src/mixins/helperMixin';
import TrainingModel from './ExpertMode/TrainingModel.vue';
import TestModel from './ExpertMode/TestModel.vue';
export default defineComponent({
  mixins: [helperMixin],
  props: {},
  components: {
    TrainingModel,
    TestModel,
  },
  watch: {},
  computed: {},
  mounted: function () {
    // this.init();
  },
  methods: {
    async deleteAllTrainings() {
      try {
        this.showLoading();
        const data = { all: true };
        const response =
          await autoAccountingApiService.deleteTrainingData(data);
        if (response.success === false) {
          throw { message: response.message };
        }
        this.clearPredictions();
        notify.success(this.$t('all_trainings_deleted'));
        this.confirm_all_training_delete = false;
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },

    async deleteCurrentSupplierTraining() {
      try {
        if (!this.isValidData() || isEmptyString(this.supplier_name)) {
          throw { message: this.$t('supplier_not_found') };
        }
        this.showLoading();
        const data = { supplier: this.supplier_name };
        const response =
          await autoAccountingApiService.deleteTrainingData(data);
        if (response.success === false) {
          throw { message: response.message };
        }
        this.clearPredictions();
        notify.success(this.$t('supplier_training_deleted'));
        this.confirm_supplier_training_delete = false;
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },
  },
  setup() {
    const auto_accounting_store = useAutoAccountingStore();
    const { is_view_readonly, supplier_name } = storeToRefs(
      auto_accounting_store,
    );
    const { clearPredictions, isValidData } = auto_accounting_store;

    return {
      isValidData,
      clearPredictions,
      is_view_readonly,
      show_popup: ref(false),
      supplier_name,
      confirm_all_training_delete: ref(false),
      confirm_supplier_training_delete: ref(false),
    };
  },
});
</script>
<style scoped lang="scss">
.fixed-height-div {
  height: 90%; /* Set the fixed height to 50% of the viewport height */
  overflow-y: auto; /* Enable vertical scrollbar when content overflows */
}
</style>
